// Independent PyTorch/torch_npu adapter. See README.md for upstream API sources.
#include <ATen/ATen.h>
#include <torch/library.h>

#include "torch_npu/csrc/core/npu/NPUCachingAllocator.h"
#include "torch_npu/csrc/core/npu/NPUFormat.h"
#include "torch_npu/csrc/core/npu/NPUGuard.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "torch_npu/csrc/framework/OpCommand.h"

#include "acl/acl.h"
#include "aclnn/acl_meta.h"
#include "aclnn_ops_repo_add.h"  // Generated by the selected, installed OPP.

#include <atomic>
#include <cstdint>
#include <dlfcn.h>
#include <limits>
#include <memory>
#include <mutex>
#include <string>
#include <vector>

namespace ops_repo {
namespace {

struct Api {
    void* handle = nullptr;
    decltype(&aclnnOpsRepoAddGetWorkspaceSize) get_workspace = nullptr;
    decltype(&aclnnOpsRepoAdd) launch = nullptr;
    std::string path;
};

Api api;
std::atomic<bool> initialized{false};
std::mutex initialize_mutex;

template <typename Function>
Function Resolve(void* handle, const char* name)
{
    dlerror();
    void* symbol = dlsym(handle, name);
    const char* error = dlerror();
    TORCH_CHECK(error == nullptr && symbol != nullptr, "ops_repo: missing OPP symbol ",
                name, ": ", error == nullptr ? "null symbol" : error);
    return reinterpret_cast<Function>(symbol);
}

void Initialize(const std::string& path)
{
    std::lock_guard<std::mutex> lock(initialize_mutex);
    if (initialized.load(std::memory_order_acquire)) {
        TORCH_CHECK(api.path == path, "ops_repo: an OPP is already loaded from ", api.path,
                    "; changing OPP requires a fresh worker process");
        return;
    }
    TORCH_CHECK(!path.empty() && path.front() == '/', "ops_repo: OPP library path must be absolute");
    void* handle = dlopen(path.c_str(), RTLD_NOW | RTLD_LOCAL);
    if (handle == nullptr) {
        const char* error = dlerror();
        TORCH_CHECK(false, "ops_repo: cannot load ", path, ": ",
                    error == nullptr ? "unknown loader error" : error);
    }
    try {
        api.get_workspace = Resolve<decltype(api.get_workspace)>(
            handle, "aclnnOpsRepoAddGetWorkspaceSize");
        api.launch = Resolve<decltype(api.launch)>(handle, "aclnnOpsRepoAdd");
        api.path = path;
        api.handle = handle;
    } catch (...) {
        dlclose(handle);
        throw;
    }
    // Keep the library resident for the process lifetime: submitted callbacks
    // and captured graphs can outlive the Python object that initialized it.
    initialized.store(true, std::memory_order_release);
}

void Check(aclnnStatus status, const char* operation)
{
    TORCH_CHECK(status == 0, "ops_repo: ", operation, " failed with ACLNN status ", status);
}

struct Invocation {
    at::Tensor x;
    at::Tensor y;
    at::Tensor z;
    at::Tensor workspace;
    std::vector<aclTensor*> descriptors;
    aclOpExecutor* executor = nullptr;
    bool repeatable = false;

    ~Invocation()
    {
        // An explicitly repeatable executor is owned by this invocation, not
        // by ACLNN phase two. It is never shared between calls or replayed here.
        // ACLNN releases ordinary executors at phase-two return, so these
        // host-side resources need not wait for device completion either.
        if (executor != nullptr) {
            if (repeatable || aclSetAclOpExecutorRepeatable(executor) == 0) {
                aclDestroyAclOpExecutor(executor);
            }
        }
        for (auto* descriptor : descriptors) {
            aclDestroyTensor(descriptor);
        }
        // Tensor storage is managed by the NPU caching allocator and recorded
        // on the launch stream; no aclrtFree or device synchronization here.
    }

    aclTensor* Describe(const at::Tensor& tensor)
    {
        const auto sizes = tensor.sizes();
        const auto strides = tensor.strides();
        // data_ptr() already includes a contiguous view's storage_offset.
        // Describe that view as a dense ND allocation starting at offset zero.
        auto* descriptor = aclCreateTensor(
            sizes.data(), sizes.size(), ACL_FLOAT, strides.data(), 0,
            ACL_FORMAT_ND, sizes.data(), sizes.size(), tensor.data_ptr());
        TORCH_CHECK(descriptor != nullptr, "ops_repo: aclCreateTensor failed");
        descriptors.push_back(descriptor);
        return descriptor;
    }
};

at::Tensor Add(const at::Tensor& x, const at::Tensor& y)
{
    TORCH_CHECK(initialized.load(std::memory_order_acquire),
                "ops_repo: bindings are not initialized; import ops_repo in this worker before executing add");
    TORCH_CHECK(x.device().type() == c10::DeviceType::PrivateUse1 && x.device() == y.device(),
                "ops_repo.add requires two tensors on the same NPU device");
    TORCH_CHECK(x.layout() == c10::kStrided && y.layout() == c10::kStrided,
                "ops_repo.add requires dense strided tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && y.scalar_type() == at::kFloat,
                "ops_repo.add supports only float32");
    TORCH_CHECK(x.sizes() == y.sizes(), "ops_repo.add requires identical shapes; no broadcasting");
    TORCH_CHECK(x.numel() > 0 && x.numel() <= std::numeric_limits<int64_t>::max() / 4,
                "ops_repo.add requires nonempty inputs whose byte size fits int64");
    TORCH_CHECK(x.is_contiguous() && y.is_contiguous(), "ops_repo.add requires contiguous inputs");
    TORCH_CHECK(!x.requires_grad() && !y.requires_grad(),
                "ops_repo.add is inference-only; inputs must have requires_grad=False");
    TORCH_CHECK(at_npu::native::get_npu_format(x) == ACL_FORMAT_ND &&
                    at_npu::native::get_npu_format(y) == ACL_FORMAT_ND,
                "ops_repo.add requires ND storage; convert format explicitly before calling");

    const c10_npu::NPUGuard guard(x.device());
    auto invocation = std::make_shared<Invocation>();
    invocation->x = x;
    invocation->y = y;
    invocation->z = at_npu::native::empty_with_format(x.sizes(), x.options(), ACL_FORMAT_ND);
    invocation->descriptors.reserve(3);
    auto* x_descriptor = invocation->Describe(x);
    auto* y_descriptor = invocation->Describe(y);
    auto* z_descriptor = invocation->Describe(invocation->z);
    uint64_t workspace_size = 0;
    Check(api.get_workspace(x_descriptor, y_descriptor, z_descriptor,
                            &workspace_size, &invocation->executor),
          "aclnnOpsRepoAddGetWorkspaceSize");
    TORCH_CHECK(invocation->executor != nullptr, "ops_repo: ACLNN returned a null executor");
    Check(aclSetAclOpExecutorRepeatable(invocation->executor), "aclSetAclOpExecutorRepeatable");
    invocation->repeatable = true;
    TORCH_CHECK(workspace_size <= static_cast<uint64_t>(std::numeric_limits<int64_t>::max()),
                "ops_repo: ACLNN workspace size exceeds int64");
    if (workspace_size != 0) {
        invocation->workspace = at_npu::native::empty_with_format(
            {static_cast<int64_t>(workspace_size)}, x.options().dtype(at::kByte), ACL_FORMAT_ND);
    }

    // Fetch the current stream for every invocation, after switching to x's
    // device. stream(false) leaves the torch_npu host task queue intact.
    const auto stream = c10_npu::getCurrentNPUStream(x.device().index());
    const aclrtStream raw_stream = stream.stream(false);
    for (const auto& tensor : {invocation->x, invocation->y, invocation->z, invocation->workspace}) {
        if (tensor.defined()) {
            c10_npu::NPUCachingAllocator::recordStream(tensor.storage().data_ptr(), stream);
        }
    }

    auto launch = [invocation, workspace_size, raw_stream]() -> int {
        // RunOpApi can defer execution to torch_npu's task thread. Shared
        // ownership retains tensors, ACL descriptors and executor until launch.
        const c10_npu::NPUGuard callback_guard(invocation->x.device());
        void* workspace = invocation->workspace.defined() ? invocation->workspace.data_ptr() : nullptr;
        Check(api.launch(workspace, workspace_size, invocation->executor, raw_stream),
              "aclnnOpsRepoAdd");
        return 0;
    };
    at_npu::native::OpCommand::RunOpApi("OpsRepoAdd", launch);
    return invocation->z;
}

}  // namespace
}  // namespace ops_repo

TORCH_LIBRARY(ops_repo, m)
{
    m.def("add(Tensor x, Tensor y) -> Tensor");
    m.def("_initialize(str op_api_library) -> ()", TORCH_FN(ops_repo::Initialize));
}

TORCH_LIBRARY_IMPL(ops_repo, PrivateUse1, m)
{
    m.impl("add", TORCH_FN(ops_repo::Add));
}

TORCH_LIBRARY_IMPL(ops_repo, AutogradPrivateUse1, m)
{
    // Add itself rejects requires_grad, even when called through torch.ops.
    m.impl("add", torch::CppFunction::makeFallthrough());
}
